import styles from './SudokuBoard.module.css'

const SudokuBoard = props => {
  const { board, solution, showSolution, onCellChange } = props;

  const renderBoard = () => board.map((cell, i) => (
    <div className={styles.cell}>
      <input
        type="text"
        pattern="\d*"
        novalidate=""
        id={`input-${i}`}
        value={showSolution ? solution[i] : cell}
        maxlength="1"
        onChange={() => onCellChange(i, cell)}
      />
    </div>
  ));

  return (
    <div className={styles.board}>
     {renderBoard()}
    </div>
  );
};

export default SudokuBoard;
